"""Symbols of the pod library that the generator owns.

Two kinds:

* Generic parts (R, C, L, diodes, crystal, test points, connectors, power symbols...) and
  ICs/modules without an easyeda2kicad symbol, drawn here as data. The IC pin tables come
  from docs/hardware/pod-v0.md or from the manufacturer datasheet cited in ``FUENTES``.
* Electrical pin types for the symbols generated by easyeda2kicad (``hardware/lib/generar.sh``),
  which come with every pin as "unspecified" and would make the ERC meaningless.

Everything uses the KiCad 8 symbol format (version 20231120), like the rest of the library.
Two-pin passives are drawn horizontal (pin 1 left) so the generated sheets read left to right.
"""

from __future__ import annotations

import math

from sexpr import Str

GENERATOR_TAG = "Generado por hardware/tools/esquematico"

FONT = ["font", ["size", "1.27", "1.27"]]


def num(value: float) -> str:
    """Format a coordinate like KiCad does (no trailing zeros, no -0)."""
    value = round(value, 4)
    if value == 0:
        return "0"
    text = f"{value:.4f}".rstrip("0").rstrip(".")
    return text


def effects(hide: bool = False, justify: str | None = None) -> list:
    node: list = ["effects", FONT]
    if justify:
        node.append(["justify"] + justify.split())
    if hide:
        node.append("hide")
    return node


def prop(name: str, value: str, x: float = 0, y: float = 0, hide: bool = False, justify: str | None = None) -> list:
    return ["property", Str(name), Str(value), ["at", num(x), num(y), "0"], effects(hide, justify)]


def stroke(width: float = 0.254, kind: str = "default") -> list:
    return ["stroke", ["width", num(width)], ["type", kind]]


def fill(kind: str = "none") -> list:
    return ["fill", ["type", kind]]


def rect(x1, y1, x2, y2, width=0.254, filled="background") -> list:
    return ["rectangle", ["start", num(x1), num(y1)], ["end", num(x2), num(y2)], stroke(width), fill(filled)]


def poly(points, width=0.254, filled="none") -> list:
    return ["polyline", ["pts"] + [["xy", num(x), num(y)] for x, y in points], stroke(width), fill(filled)]


def circle(cx, cy, r, width=0.254, filled="none") -> list:
    return ["circle", ["center", num(cx), num(cy)], ["radius", num(r)], stroke(width), fill(filled)]


def arc(start, mid, end, width=0.254) -> list:
    return ["arc", ["start", num(start[0]), num(start[1])], ["mid", num(mid[0]), num(mid[1])],
            ["end", num(end[0]), num(end[1])], stroke(width), fill("none")]


def text(value, x, y) -> list:
    return ["text", Str(value), ["at", num(x), num(y), "0"], effects()]


def pin(kind: str, x: float, y: float, angle: int, length: float, name: str, number: str, hide: bool = False) -> list:
    node = ["pin", kind, "line", ["at", num(x), num(y), str(angle)], ["length", num(length)]]
    if hide:
        node.append("hide")
    node.append(["name", Str(name), effects()])
    node.append(["number", Str(number), effects()])
    return node


def symbol(name: str, ref: str, graphics: list, pins: list, *, value: str | None = None, footprint: str = "",
           datasheet: str = "", description: str = "", power: bool = False, hide_pin_names: bool = False,
           hide_pin_numbers: bool = False, in_bom: bool = True, on_board: bool = True,
           ref_at=(0, 2.54), value_at=(0, -2.54), hide_value: bool = False) -> list:
    node: list = ["symbol", Str(name)]
    if power:
        node.append(["power"])
    if hide_pin_numbers:
        node.append(["pin_numbers", "hide"])
    if hide_pin_names:
        node.append(["pin_names", ["offset", "0"], "hide"])
    else:
        node.append(["pin_names", ["offset", "1.016"]])
    node.append(["exclude_from_sim", "no"])
    node.append(["in_bom", "yes" if in_bom else "no"])
    node.append(["on_board", "yes" if on_board else "no"])
    node.append(prop("Reference", ref, ref_at[0], ref_at[1], hide=power))
    node.append(prop("Value", value if value is not None else name, value_at[0], value_at[1], hide=hide_value))
    node.append(prop("Footprint", footprint, hide=True))
    node.append(prop("Datasheet", datasheet or "~", hide=True))
    node.append(prop("Description", description or name, hide=True))
    node.append(prop("Generador", GENERATOR_TAG, hide=True))
    node.append(["symbol", Str(f"{name}_0_1")] + graphics)
    node.append(["symbol", Str(f"{name}_1_1")] + pins)
    return node


# ---------------------------------------------------------------------------
# Generic two-pin parts (horizontal, pin 1 on the left at x = -3.81 or -2.54).


def two_pin(name, ref, graphics, *, x=3.81, length=1.27, kind="passive", names=("~", "~"), numbers=("1", "2"),
            description="", footprint="", hide_names=True, value_y=-2.54):
    pins = [
        pin(kind, -x, 0, 0, length, names[0], numbers[0]),
        pin(kind, x, 0, 180, length, names[1], numbers[1]),
    ]
    return symbol(name, ref, graphics, pins, description=description, footprint=footprint,
                  hide_pin_names=hide_names, hide_pin_numbers=True, ref_at=(0, 2.54), value_at=(0, value_y))


def generic_symbols() -> list:
    syms = []
    syms.append(two_pin("R", "R", [rect(-2.54, 0.889, 2.54, -0.889, filled="none")],
                        description="Resistencia (horizontal, pin 1 a la izquierda)"))
    syms.append(two_pin("C", "C", [poly([(-0.508, 1.524), (-0.508, -1.524)], 0.3048),
                                   poly([(0.508, 1.524), (0.508, -1.524)], 0.3048)],
                        x=2.54, length=2.032, description="Capacitor"))
    bumps = []
    for i in range(4):
        x0 = -2.54 + i * 1.27
        bumps.append(arc((x0, 0), (x0 + 0.635, 0.635), (x0 + 1.27, 0)))
    syms.append(two_pin("L", "L", bumps, description="Inductor"))
    # Diode: pin 2 = anode on the left, pin 1 = cathode on the right (KiCad's Device:D numbering).
    diode = [poly([(-1.27, 1.27), (-1.27, -1.27), (1.27, 0), (-1.27, 1.27)], 0.254, "none"),
             poly([(1.27, 1.27), (1.27, -1.27)], 0.254), poly([(-2.54, 0), (2.54, 0)], 0)]
    syms.append(two_pin("D", "D", diode, names=("A", "K"), numbers=("2", "1"), description="Diodo (A izquierda, K derecha)"))
    tvs_uni = [poly([(-1.27, 1.27), (-1.27, -1.27), (1.27, 0), (-1.27, 1.27)], 0.254, "none"),
               poly([(0.762, 1.27), (1.27, 1.27), (1.27, -1.27), (1.778, -1.27)], 0.254), poly([(-2.54, 0), (2.54, 0)], 0)]
    syms.append(two_pin("D_TVS", "D", tvs_uni, names=("A", "K"), numbers=("2", "1"),
                        description="TVS unidireccional (A izquierda, K derecha)"))
    tvs_bi = [poly([(-2.54, 1.27), (-2.54, -1.27), (0, 0), (-2.54, 1.27)], 0.254, "none"),
              poly([(2.54, 1.27), (2.54, -1.27), (0, 0), (2.54, 1.27)], 0.254, "none"),
              poly([(-0.508, 1.27), (0, 1.27), (0, -1.27), (0.508, -1.27)], 0.254)]
    syms.append(two_pin("D_ESD", "D", tvs_bi, x=5.08, length=2.54,
                        description="Protección ESD/TVS bidireccional de una línea"))
    xtal = [rect(-1.143, 1.905, 1.143, -1.905, filled="none"), poly([(-2.032, 1.27), (-2.032, -1.27)], 0.3048),
            poly([(2.032, 1.27), (2.032, -1.27)], 0.3048)]
    syms.append(two_pin("Crystal", "Y", xtal, description="Cristal de dos pines"))
    jumper = [arc((-0.254, 1.016), (-1.27, 0), (-0.254, -1.016)), arc((0.254, -1.016), (1.27, 0), (0.254, 1.016)),
              poly([(-0.254, 1.016), (-0.254, -1.016)], 0.254), poly([(0.254, 1.016), (0.254, -1.016)], 0.254),
              rect(-0.254, 0.508, 0.254, -0.508, 0, "outline")]
    syms.append(two_pin("SolderJumper_Bridged", "JP", jumper, x=3.81, length=2.54,
                        description="Puente de soldadura cerrado (se corta para abrir)"))
    sw = [circle(-1.524, 0, 0.508), circle(1.524, 0, 0.508), poly([(-1.524, 0.762), (1.524, 1.524)], 0.254),
          poly([(0, 1.27), (0, 2.54)], 0.254)]
    syms.append(two_pin("SW_Push", "SW", sw, x=5.08, length=3.048, description="Pulsador normalmente abierto"))
    buz = [circle(0, 0, 1.778), text("+", -1.016, 1.778)]
    syms.append(two_pin("Buzzer", "BZ", buz, x=5.08, length=3.302, names=("+", "-"), hide_names=True,
                        description="Buzzer (pin 1 +, pin 2 -)", value_y=-3.81))

    # One-pin parts.
    syms.append(symbol("TestPoint", "TP", [circle(0.762, 0, 0.762)],
                       [pin("passive", -2.54, 0, 0, 2.54, "1", "1")], description="Pad de prueba",
                       hide_pin_names=True, hide_pin_numbers=True, ref_at=(0, 2.54), value_at=(0, -2.54)))
    syms.append(symbol("Antenna", "AE", [poly([(0, 0), (0, 3.81)], 0.254), poly([(-1.27, 3.81), (0, 1.905), (1.27, 3.81), (-1.27, 3.81)], 0.254)],
                       [pin("passive", -2.54, 0, 0, 2.54, "A", "1")], description="Antena (pin de alimentación)",
                       hide_pin_names=True, hide_pin_numbers=True, ref_at=(2.54, 2.54), value_at=(2.54, -2.54)))
    syms.append(symbol("Shield", "SH", [rect(-1.27, 2.54, 3.81, -2.54, 0.254, "none")],
                       [pin("passive", -3.81, 0, 0, 2.54, "GND", "1")], description="Tapa blindada (lugar para soldarla)",
                       hide_pin_names=True, hide_pin_numbers=True, ref_at=(1.27, 3.81), value_at=(1.27, -3.81)))
    # Footprint-only parts (no pins): fiducials and tooling holes.
    syms.append(symbol("Fiducial", "FID", [circle(0, 0, 1.27, 0.254, "outline")], [], description="Fiducial (solo footprint)",
                       in_bom=False, ref_at=(0, 2.54), value_at=(0, -2.54)))
    syms.append(symbol("MountingHole", "H", [circle(0, 0, 1.27, 0.254, "none")], [], description="Agujero sin cobre (solo footprint)",
                       in_bom=False, ref_at=(0, 2.54), value_at=(0, -2.54)))
    return syms


# ---------------------------------------------------------------------------
# Block (IC-style) symbols: rectangle body, pins left and right, 2.54 mm pitch.

CHAR_W = 1.1  # approximate width of a 1.27 mm character in KiCad's stroke font


def block(name: str, ref: str, left: list, right: list, *, description: str = "", datasheet: str = "",
          footprint: str = "", title: str | None = None, min_half_width: float = 5.08) -> list:
    """``left``/``right``: lists of (number, name, type) or None for an empty row."""
    def longest(side):
        return max([len(p[1]) for p in side if p] + [0])

    half = max(min_half_width, (longest(left) + longest(right)) * CHAR_W / 2 + 2.54)
    half = math.ceil(half / 2.54) * 2.54
    rows = max(len(left), len(right), 1)
    top = math.ceil((rows - 1) / 2) * 2.54
    pins = []
    for i, p in enumerate(left):
        if p:
            pins.append(pin(p[2], -half - 2.54, top - i * 2.54, 0, 2.54, p[1], p[0]))
    for i, p in enumerate(right):
        if p:
            pins.append(pin(p[2], half + 2.54, top - i * 2.54, 180, 2.54, p[1], p[0]))
    body_top = top + 2.54
    body_bottom = top - (rows - 1) * 2.54 - 2.54
    graphics = [rect(-half, body_top, half, body_bottom)]
    if title:
        graphics.append(text(title, 0, body_bottom + 1.27))
    return symbol(name, ref, graphics, pins, description=description, datasheet=datasheet, footprint=footprint,
                  ref_at=(-half, body_top + 1.27), value_at=(-half, body_bottom - 1.27))


PI, PO, IN, OUT, BI, PAS, TRI, OC, NC = (
    "power_in", "power_out", "input", "output", "bidirectional", "passive", "tri_state", "open_collector", "no_connect")


def ic_symbols() -> list:
    s = []
    # Quectel LC29H: Hardware Design V1.0, table 5 (pin table copied in pod-v0.md, "Pines del LC29H").
    s.append(block("LC29H", "U", [
        ("23", "VCC", PI), ("22", "V_BCKP", PI), ("7", "VDD_EXT", PO), ("9", "VDD_RF", PO), None,
        ("11", "RF_IN", PAS), ("14", "ANT_ON", OUT), None,
        ("10", "GND", PI), ("12", "GND", PI), ("13", "GND", PI), ("24", "GND", PI),
    ], [
        ("1", "WAKEUP", IN), ("8", "RESET_N", IN), ("3", "1PPS", OUT), ("20", "TXD", OUT), ("21", "RXD", IN),
        ("18", "I2C_SDA", BI), ("19", "I2C_SCL", BI), ("2", "FWD", IN), ("4", "WHEELTICK", IN),
        ("5", "RESERVED", NC), ("6", "RESERVED", NC), ("15", "RESERVED", NC), ("16", "RESERVED", NC), ("17", "RESERVED", NC),
    ], description="Quectel LC29H (AA/EA), GNSS L1/L5, LCC de 24 pines, E/S de 2,8 V",
        datasheet="https://forums.quectel.com/uploads/short-url/6AJSfkCWZOBEg7psU3USNgfcBqm.pdf"))
    # TI TPS63900, SLVSET3D table 5-1 (WSON-10 DSK).
    s.append(block("TPS63900", "U", [
        ("10", "VIN", PI), ("1", "EN", IN), ("2", "SEL", IN), None, ("9", "LX1", PAS), ("7", "LX2", PAS),
    ], [
        ("6", "VOUT", PO), ("3", "CFG1", PAS), ("4", "CFG2", PAS), ("5", "CFG3", PAS), ("8", "GND", PI), ("11", "EP", PAS),
    ], description="Buck-boost 1,8–5,5 V, 75 nA, salida por resistencias de CFG", datasheet="https://www.ti.com/lit/ds/symlink/tps63900.pdf"))
    # TI TPS25947 (TPS259470x), SLVSFC9C table 5-1 (VQFN-10 RPW).
    s.append(block("TPS259470", "U", [
        ("5", "IN", PI), ("1", "EN/UVLO", IN), ("2", "OVLO", IN), ("8", "GND", PI),
    ], [
        ("6", "OUT", PO), ("9", "ILM", PAS), ("7", "DVDT", PAS), ("10", "ITIMER", PAS), ("3", "AUXOFF", OC), ("4", "~{FLT}", OC),
    ], description="eFuse 2,7–23 V con OVLO ajustable y bloqueo de corriente inversa", datasheet="https://www.ti.com/lit/ds/symlink/tps25947.pdf"))
    # TI TPS7A20 / TPS7A02 SOT-23-5 (DBV): 1 IN, 2 GND, 3 EN, 4 NC, 5 OUT (both datasheets, table of pins).
    for name, desc, ds in (("TPS7A20_DBV", "LDO de bajo ruido 300 mA, EN con pull-down de 500 kΩ y descarga de 150 Ω", "https://www.ti.com/lit/ds/symlink/tps7a20.pdf"),
                           ("TPS7A02_DBV", "LDO de 25 nA, EN con pull-down interno", "https://www.ti.com/lit/ds/symlink/tps7a02.pdf")):
        s.append(block(name, "U", [("1", "IN", PI), ("3", "EN", IN), ("4", "NC", NC)], [("5", "OUT", PO), ("2", "GND", PI)],
                       description=desc, datasheet=ds))
    # TI TPS22916 YFP (DSBGA-4), SLVSDO5F table 5-1. VOUT drawn as passive: it is a switch, and the rail
    # after it carries its own PWR_FLAG (so a not-mounted switch never ends up as a rail's only driver).
    s.append(block("TPS22916", "U", [("A2", "VIN", PI), ("B2", "ON", IN)], [("A1", "VOUT", PAS), ("B1", "GND", PI)],
                   description="Load switch de 2 A, 1–5,5 V", datasheet="https://www.ti.com/lit/ds/symlink/tps22916.pdf"))
    # TI SN74LVC1T45 DBV/DCK, SCES515N table 4-1. DIR high: A -> B; low: B -> A.
    s.append(block("SN74LVC1T45", "U", [("1", "VCCA", PI), ("3", "A", BI), ("5", "DIR", IN)], [("6", "VCCB", PI), ("4", "B", BI), ("2", "GND", PI)],
                   description="Traductor de un bit, DIR alto = A a B", datasheet="https://www.ti.com/lit/ds/symlink/sn74lvc1t45.pdf"))
    # ST USBLC6-2SC6 (KiCad's Power_Protection:USBLC6-2P6 pin numbers).
    s.append(block("USBLC6-2SC6", "U", [("1", "I/O1", PAS), ("6", "I/O1", PAS), ("5", "VBUS", PAS)], [("3", "I/O2", PAS), ("4", "I/O2", PAS), ("2", "GND", PAS)],
                   description="ESD de baja capacidad para D+/D−", datasheet="https://www.st.com/resource/en/datasheet/usblc6-2.pdf"))
    # Qorvo DWM3000: KiCad's RF_Module:DWM3000 (extends DWM1000) pin numbers. Pin 5 is VDDAON in the
    # DWM1000 and differs in the DWM3000 (KiCad MR 4169): drawn passive and left to a 0 Ω.
    s.append(block("DWM3000", "U", [
        ("6", "VDD3V3", PI), ("7", "VDD3V3", PI), ("5", "VDD1/VDDAON", PAS), None,
        ("1", "EXTON", OUT), ("2", "WAKEUP", BI), ("3", "~{RST}", BI), ("22", "IRQ/GPIO8", BI), None,
        ("8", "VSS", PI), ("16", "VSS", PI), ("21", "VSS", PI), ("23", "VSS", PI), ("24", "VSS", PI),
    ], [
        ("17", "~{SPICS}", IN), ("20", "SPICLK", IN), ("18", "SPIMOSI", IN), ("19", "SPIMISO", TRI), None,
        ("15", "GPIO0", BI), ("14", "GPIO1", BI), ("13", "GPIO2", BI), ("12", "GPIO3", BI), ("11", "GPIO4", BI),
        ("10", "GPIO5/SPIPOL", BI), ("9", "GPIO6/SPIHA", BI), ("4", "GPIO7", BI),
    ], description="Módulo UWB Qorvo DWM3000 (pines de la librería oficial de KiCad, sin verificar contra la hoja)",
        datasheet="https://www.qorvo.com/products/d/da008142"))
    # TDK ICM-42688-P (LGA-14). Pin table from general knowledge of the part: NOT verified.
    s.append(block("ICM-42688-P", "U", [
        ("8", "VDD", PI), ("5", "VDDIO", PI), ("6", "GND", PI), None, ("4", "INT1", OUT), ("9", "INT2/FSYNC", BI),
    ], [
        ("12", "AP_CS", IN), ("13", "AP_SCLK", IN), ("14", "AP_SDI", BI), ("1", "AP_SDO", TRI), None,
        ("2", "RESV", PAS), ("3", "RESV", PAS), ("7", "RESV", PAS), ("10", "RESV", PAS), ("11", "RESV", PAS),
    ], description="IMU de 6 ejes TDK ICM-42688-P (numeración de pines sin verificar)"))
    # Analog Devices ADXL372 (LGA-16). Pin table NOT verified (assumed like the ADXL362 family).
    s.append(block("ADXL372", "U", [
        ("14", "VS", PI), ("1", "VDDIO", PI), ("12", "GND", PI), ("13", "GND", PI), ("16", "GND", PI), None,
        ("11", "INT1", OUT), ("9", "INT2", OUT),
    ], [
        ("8", "~{CS}", IN), ("4", "SCLK", IN), ("6", "MOSI", IN), ("7", "MISO", TRI), None,
        ("2", "NC", PAS), ("3", "RES", PAS), ("5", "RES", PAS), ("10", "RES", PAS), ("15", "RES", PAS),
    ], description="Acelerómetro de ±200 g ADXL372 (numeración de pines sin verificar)"))
    # Generic placeholders: part not chosen yet (pod-v0.md: dual-band L1 + L5, no verificado).
    s.append(block("SAW_L1L5", "FL", [("1", "IN", PAS), ("2", "GND", PI)], [("3", "OUT", PAS), ("4", "GND", PI)],
                   description="Filtro SAW L1 + L5 (parte por elegir; pines genéricos)", min_half_width=3.81))
    s.append(block("LNA_L1L5", "U", [("1", "RFIN", PAS), ("2", "VCC", PI), ("3", "EN", IN)], [("4", "RFOUT", PAS), ("5", "GND", PI)],
                   description="LNA L1 + L5 (parte por elegir; pines genéricos)", min_half_width=3.81))
    # Discrete transistors, SOT-23 standard numbering (1 G, 2 S, 3 D).
    s.append(block("Q_NMOS_GSD", "Q", [("1", "G", IN)], [("3", "D", PAS), ("2", "S", PAS)],
                   description="NMOS de nivel lógico, SOT-23 (1 G, 2 S, 3 D)", min_half_width=2.54))
    s.append(block("Q_PMOS_GSD", "Q", [("1", "G", IN)], [("3", "D", PAS), ("2", "S", PAS)],
                   description="PMOS, SOT-23 (1 G, 2 S, 3 D)", min_half_width=2.54))
    # Connectors.
    s.append(block("Conn_Coax", "J", [("1", "IN", PAS)], [("2", "Ext", PAS)], description="Conector coaxial (U.FL)", min_half_width=2.54))
    s.append(block("Conn_Bateria", "J", [], [("1", "BAT", PAS), ("2", "GND", PAS), ("3", "NTC", PAS), ("MP", "MP", PAS)],
                   description="Conector de batería con llave: BAT, GND, NTC"))
    s.append(block("Conn_01x04_MP", "J", [], [("1", "1", PAS), ("2", "2", PAS), ("3", "3", PAS), ("4", "4", PAS), ("MP", "MP", PAS)],
                   description="Conector de 4 pines con pads de montaje"))
    s.append(block("Pads_Base", "J", [], [("1", "VBUS", PAS), ("2", "D+", PAS), ("3", "D-", PAS), ("4", "GND", PAS), ("5", "DETECT", PAS)],
                   description="5 pads planos dorados con llave hacia la base (resortes pogo en la base)"))
    s.append(block("TC2030-NL", "J", [], [("1", "VCC", PAS), ("2", "SWDIO", PAS), ("3", "~{RESET}", PAS), ("4", "SWCLK", PAS), ("5", "GND", PAS), ("6", "SWO", PAS)],
                   description="Tag-Connect TC2030-NL, pinout SWD de ARM"))
    return s


def power_symbols(names) -> list:
    syms = []
    for name in names:
        if name == "GND":
            g = [poly([(0, 0), (0, -1.27), (1.27, -1.27), (0, -2.54), (-1.27, -1.27), (0, -1.27)], 0)]
            syms.append(symbol("GND", "#PWR", g, [pin("power_in", 0, 0, 270, 0, "GND", "1", hide=True)], power=True,
                               description="Tierra", hide_pin_names=True, ref_at=(0, -6.35), value_at=(0, -3.81),
                               hide_value=True))
        else:
            g = [poly([(-0.762, 1.27), (0, 2.54)], 0), poly([(0, 0), (0, 2.54)], 0), poly([(0, 2.54), (0.762, 1.27)], 0)]
            syms.append(symbol(name, "#PWR", g, [pin("power_in", 0, 0, 90, 0, name, "1", hide=True)], power=True,
                               description=f"Riel {name}", hide_pin_names=True, ref_at=(0, -3.81), value_at=(0, 3.556)))
    flag = [poly([(0, 0), (0, 1.27), (-1.016, 1.905), (0, 2.54), (1.016, 1.905), (0, 1.27)], 0)]
    syms.append(symbol("PWR_FLAG", "#FLG", flag, [pin("power_out", 0, 0, 90, 0, "pwr", "1", hide=True)], power=True,
                       description="Marca de fuente para el ERC", hide_pin_names=True, ref_at=(0, 1.905), value_at=(0, 3.81)))
    return syms


